    30  static void *
    31  multicastWorkerLoop(UA_Server *server) {
    32      struct timeval next_sleep = {.tv_sec = 0, .tv_usec = 0};
    33      volatile UA_Boolean *running = &server->mdnsRunning;
    34      fd_set fds;
    35
    36      while(*running) {
    37          FD_ZERO(&fds);
    38          FD_SET(server->mdnsSocket, &fds);
    39          select(server->mdnsSocket + 1, &fds, 0, 0, &next_sleep);
    40
    41          if(!*running)
    42              break;
    43
    44          unsigned short retVal =
    45              mdnsd_step(server->mdnsDaemon, server->mdnsSocket,
    46                         FD_ISSET(server->mdnsSocket, &fds), true, &next_sleep);
    47          if (retVal == 1) {
    48              UA_LOG_ERROR(server->config.logger, UA_LOGCATEGORY_SERVER,
    49                           "Multicast error: Can not read from socket. %s",
    50                           strerror(errno));
    51              break;
    52          } else if (retVal == 2) {
    53              UA_LOG_ERROR(server->config.logger, UA_LOGCATEGORY_SERVER,
    54                           "Multicast error: Can not write to socket. %s",
    55                           strerror(errno));
    56              break;
    57          }
    58      }
    59      return NULL;
    60  }
