    62  static UA_StatusCode
    63  multicastListenStart(UA_Server* server) {
    64      int err = pthread_create(&server->mdnsThread, NULL,
    65                               (void* (*)(void*))multicastWorkerLoop, server);
    66      if(err != 0) {
    67          UA_LOG_ERROR(server->config.logger, UA_LOGCATEGORY_SERVER,
    68                       "Multicast error: Can not create multicast thread.");
    69          return UA_STATUSCODE_BADUNEXPECTEDERROR;
    70      }
    71      return UA_STATUSCODE_GOOD;
    72  }
    73
    74  static UA_StatusCode
    75  multicastListenStop(UA_Server* server) {
    76      mdnsd_shutdown(server->mdnsDaemon);
    77      // wake up select
    78      write(server->mdnsSocket, "\0", 1);
    79      if(pthread_join(server->mdnsThread, NULL)) {
    80          UA_LOG_ERROR(server->config.logger, UA_LOGCATEGORY_SERVER,
    81                       "Multicast error: Can not stop thread.");
    82          return UA_STATUSCODE_BADUNEXPECTEDERROR;
    83      }
    84      return UA_STATUSCODE_BADNOTIMPLEMENTED;
    85  }
