    90  addMdnsRecordForNetworkLayer(UA_Server *server, const UA_String *appName,
    91                               const UA_ServerNetworkLayer* nl) {
    92      UA_String hostname = UA_STRING_NULL;
    93      UA_UInt16 port = 4840;
    94      UA_String path = UA_STRING_NULL;
    95      UA_StatusCode retval = UA_parseEndpointUrl(&nl->discoveryUrl, &hostname,
