    97      if(retval != UA_STATUSCODE_GOOD) {
    98          UA_LOG_WARNING(server->config.logger, UA_LOGCATEGORY_NETWORK,
    99                         "Server url is invalid: %.*s",
   100                         (int)nl->discoveryUrl.length, nl->discoveryUrl.data);
   101          return retval;
   102      }
   103      UA_Discovery_addRecord(server, appName, &hostname, port,
   104                             &path, UA_DISCOVERY_TCP, UA_TRUE,
   105                             server->config.serverCapabilities,
   106                             &server->config.serverCapabilitiesSize);
   107      return UA_STATUSCODE_GOOD;
   108  }
