   110  void startMulticastDiscoveryServer(UA_Server *server) {
   111      UA_String *appName = &server->config.mdnsServerName;
   112      for(size_t i = 0; i < server->config.networkLayersSize; i++)
   113          addMdnsRecordForNetworkLayer(server, appName, &server->config.networkLayers[i]);
   114
   115      /* find any other server on the net */
   116      UA_Discovery_multicastQuery(server);
   117
   118  # ifdef UA_ENABLE_MULTITHREADING
   119      multicastListenStart(server);
   120  # endif
   121  }
