   142  /* All filter criteria must be fulfilled */
   143  static UA_Boolean
   144  filterServerRecord(size_t serverCapabilityFilterSize, UA_String *serverCapabilityFilter,
   145                     serverOnNetwork_list_entry* current) {
   146      for(size_t i = 0; i < serverCapabilityFilterSize; i++) {
   147          for(size_t j = 0; j < current->serverOnNetwork.serverCapabilitiesSize; j++)
   148              if(!UA_String_equal(&serverCapabilityFilter[i],
   149                                  &current->serverOnNetwork.serverCapabilities[j]))
   150                  return false;
   151      }
   152      return true;
   153  }
