   155  void Service_FindServersOnNetwork(UA_Server *server, UA_Session *session,
   156                                    const UA_FindServersOnNetworkRequest *request,
   157                                    UA_FindServersOnNetworkResponse *response) {
   158      /* Set LastCounterResetTime */
   159      UA_DateTime_copy(&server->serverOnNetworkRecordIdLastReset,
   160                       &response->lastCounterResetTime);
   161
   162      /* Compute the max number of records to return */
   163      UA_UInt32 recordCount = 0;
   164      if(request->startingRecordId < server->serverOnNetworkRecordIdCounter)
   165          recordCount = server->serverOnNetworkRecordIdCounter - request->startingRecordId;
   166      if(request->maxRecordsToReturn && recordCount > request->maxRecordsToReturn)
   167          recordCount = MIN(recordCount, request->maxRecordsToReturn);
   168      if(recordCount == 0) {
   169          response->serversSize = 0;
   170          return;
   171      }
   172
   173      /* Iterate over all records and add to filtered list */
   174      UA_UInt32 filteredCount = 0;
   175      UA_ServerOnNetwork** filtered =
   176          (UA_ServerOnNetwork**)UA_alloca(sizeof(UA_ServerOnNetwork*) * recordCount);
   177      serverOnNetwork_list_entry* current;
   178      LIST_FOREACH(current, &server->serverOnNetwork, pointers) {
   179          if(filteredCount >= recordCount)
   180              break;
   181          if(current->serverOnNetwork.recordId < request->startingRecordId)
   182              continue;
   183          if(!filterServerRecord(request->serverCapabilityFilterSize,
   184                                 request->serverCapabilityFilter, current))
   185              continue;
   186          filtered[filteredCount++] = &current->serverOnNetwork;
   187      }
   188
   189      if(filteredCount == 0)
   190          return;
   191
   192      /* Allocate the array for the response */
   193      response->servers =
   194          (UA_ServerOnNetwork*)UA_malloc(sizeof(UA_ServerOnNetwork)*filteredCount);
   195      if(!response->servers) {
   196          response->responseHeader.serviceResult = UA_STATUSCODE_BADOUTOFMEMORY;
   197          return;
   198      }
   199      response->serversSize = filteredCount;
   200
   201      /* Copy the server names */
   202      for(size_t i = 0; i < filteredCount; i++)
   203          UA_ServerOnNetwork_copy(filtered[i], &response->servers[filteredCount-i-1]);
   204  }
