   237          capabilitiesSize = mdnsConfig->serverCapabilitiesSize;
   238      }
   239
   240      UA_StatusCode addRetval =
   241          UA_Discovery_addRecord(server, serverName, &hostname,
   242                                 port, &path, UA_DISCOVERY_TCP, updateTxt,
   243                                 capabilities, &capabilitiesSize);
   244      if(addRetval != UA_STATUSCODE_GOOD)
   245          UA_LOG_WARNING(server->config.logger, UA_LOGCATEGORY_SERVER,
   246                         "Could not add mDNS record for hostname %.*s.",
   247                         (int)serverName->length, serverName->data);
